/**
 * On-device message scoring.
 *
 * This is a faithful port of the scikit-learn pipeline exported by
 * `ml/export_model.py`: a FeatureUnion of a word (1-2 gram) and a character
 * (3-5 gram) TF-IDF vectoriser feeding a logistic regression, with a single
 * Platt sigmoid fitted on validation.
 *
 * It exists so that message text never has to leave the device to be scored.
 * That is the whole privacy argument of the product, so the port is held to
 * exact parity with sklearn by `tests/scorer.parity.test.ts`, which replays
 * fixtures generated by the training script.
 *
 * The places this implementation is easy to get wrong, and what sklearn
 * actually does, are commented inline. They are all whitespace, unicode and
 * normalisation details.
 */

export interface VectorizerSpec {
  /** Inclusive [min, max] n-gram range. */
  ngram: [number, number];
  /** Vocabulary terms, in feature-index order. */
  terms: string[];
  /** Inverse document frequency per feature index. */
  idf: number[];
}

export interface ScoringModel {
  format: string;
  word: VectorizerSpec;
  char: VectorizerSpec;
  coefWord: number[];
  coefChar: number[];
  intercept: number;
  platt: { a: number; b: number };
  threshold: number;
  abstain: { low: number; high: number };
}

/**
 * sklearn's default `token_pattern` is `(?u)\b\w\w+\b`, which in practice
 * selects every maximal run of word characters of length two or more. Python's
 * `\w` under unicode is letters, digits and underscore, so the JS equivalent
 * needs explicit unicode property escapes — a plain `\w` here would be
 * ASCII-only and would silently drop every accented word.
 */
const WORD_RUN = /[\p{L}\p{N}_]+/gu;

/**
 * `CountVectorizer._char_ngrams` collapses runs of two or more whitespace
 * characters into a single space before slicing. A single newline is left
 * alone. Getting this wrong shifts every character n-gram in a multi-line
 * thread.
 */
const WHITESPACE_RUN = /\s\s+/gu;

export function wordTokens(text: string): string[] {
  const lowered = text.toLowerCase();
  const out: string[] = [];
  for (const match of lowered.matchAll(WORD_RUN)) {
    if (match[0].length >= 2) out.push(match[0]);
  }
  return out;
}

export function wordNgrams(text: string, [minN, maxN]: [number, number]): string[] {
  const tokens = wordTokens(text);
  const out: string[] = [];
  let start = minN;
  if (minN === 1) {
    out.push(...tokens);
    start = 2;
  }
  for (let n = start; n <= Math.min(maxN, tokens.length); n += 1) {
    for (let i = 0; i <= tokens.length - n; i += 1) {
      out.push(tokens.slice(i, i + n).join(" "));
    }
  }
  return out;
}

export function charNgrams(text: string, [minN, maxN]: [number, number]): string[] {
  const collapsed = text.toLowerCase().replace(WHITESPACE_RUN, " ");
  // Python indexes strings by code point; JS indexes by UTF-16 code unit. For
  // anything outside the BMP (emoji, which the adversarial suite uses heavily)
  // those disagree, so slice over code points explicitly.
  const chars = Array.from(collapsed);
  const len = chars.length;
  const out: string[] = [];
  let start = minN;
  if (minN === 1) {
    out.push(...chars);
    start = 2;
  }
  for (let n = start; n <= Math.min(maxN, len); n += 1) {
    for (let i = 0; i <= len - n; i += 1) {
      out.push(chars.slice(i, i + n).join(""));
    }
  }
  return out;
}

/** A sparse TF-IDF row: feature index -> L2-normalised weight. */
export type SparseRow = Map<number, number>;

class Vectorizer {
  private readonly index: Map<string, number>;

  constructor(
    private readonly spec: VectorizerSpec,
    private readonly analyzer: (text: string, ngram: [number, number]) => string[],
  ) {
    this.index = new Map();
    for (let i = 0; i < spec.terms.length; i += 1) this.index.set(spec.terms[i], i);
  }

  transform(text: string): SparseRow {
    const counts = new Map<number, number>();
    for (const gram of this.analyzer(text, this.spec.ngram)) {
      const j = this.index.get(gram);
      if (j !== undefined) counts.set(j, (counts.get(j) ?? 0) + 1);
    }

    // sublinear_tf=True  ->  tf = 1 + ln(count), then multiplied by idf.
    const row: SparseRow = new Map();
    let sumSquares = 0;
    for (const [j, count] of counts) {
      const value = (1 + Math.log(count)) * this.spec.idf[j];
      row.set(j, value);
      sumSquares += value * value;
    }

    // norm='l2'. An all-zero row (no known terms, or empty input) is left as
    // zeros rather than divided — matching sklearn, which skips empty rows.
    if (sumSquares > 0) {
      const norm = Math.sqrt(sumSquares);
      for (const [j, value] of row) row.set(j, value / norm);
    }
    return row;
  }
}

export interface FeatureContribution {
  term: string;
  block: "word" | "char";
  /** Signed contribution to the decision margin. */
  contribution: number;
}

export interface ScoreResult {
  /** Raw logistic decision-function value, before calibration. */
  margin: number;
  /** Calibrated probability that this text belongs to the scam class. */
  probability: number;
  /** True when the probability sits inside the abstain band. */
  abstain: boolean;
}

export class Scorer {
  private readonly wordVec: Vectorizer;
  private readonly charVec: Vectorizer;

  constructor(private readonly model: ScoringModel) {
    this.wordVec = new Vectorizer(model.word, wordNgrams);
    this.charVec = new Vectorizer(model.char, charNgrams);
  }

  get threshold(): number {
    return this.model.threshold;
  }

  get abstainBand(): { low: number; high: number } {
    return this.model.abstain;
  }

  margin(text: string): number {
    const wordRow = this.wordVec.transform(text);
    const charRow = this.charVec.transform(text);
    let margin = this.model.intercept;
    for (const [j, value] of wordRow) margin += value * this.model.coefWord[j];
    for (const [j, value] of charRow) margin += value * this.model.coefChar[j];
    return margin;
  }

  score(text: string): ScoreResult {
    const margin = this.margin(text);
    const { a, b } = this.model.platt;
    const probability = 1 / (1 + Math.exp(-(a * margin + b)));
    const { low, high } = this.model.abstain;
    return {
      margin,
      probability,
      abstain: probability >= low && probability < high,
    };
  }

  /**
   * The features that moved this particular score, most influential first.
   *
   * Used by the decision receipt. This is the model's actual arithmetic, not a
   * generated rationalisation — which matters, because the explainer is only
   * ever allowed to phrase facts that came from here or from the deterministic
   * signal detectors.
   */
  contributions(text: string, limit = 8): FeatureContribution[] {
    const out: FeatureContribution[] = [];
    for (const [j, value] of this.wordVec.transform(text)) {
      out.push({
        term: this.model.word.terms[j],
        block: "word",
        contribution: value * this.model.coefWord[j],
      });
    }
    for (const [j, value] of this.charVec.transform(text)) {
      out.push({
        term: this.model.char.terms[j],
        block: "char",
        contribution: value * this.model.coefChar[j],
      });
    }
    out.sort((x, y) => Math.abs(y.contribution) - Math.abs(x.contribution));
    return out.slice(0, limit);
  }
}

let cached: Promise<Scorer> | null = null;

/**
 * Fetch and cache the model in the browser.
 *
 * The asset is immutable and long-cached, so this is one request per install.
 * Nothing is posted anywhere: the download is the only network traffic the
 * scoring path ever generates.
 */
export function loadScorer(basePath = "/model/model.json"): Promise<Scorer> {
  if (!cached) {
    cached = fetch(basePath)
      .then((res) => {
        if (!res.ok) throw new Error(`Could not load scoring model (${res.status})`);
        return res.json() as Promise<ScoringModel>;
      })
      .then((model) => new Scorer(model))
      .catch((err) => {
        cached = null;
        throw err;
      });
  }
  return cached;
}
